const SVG_NS = 'http://www.w3.org/2000/svg';

export function icon(name, size = 18, extraClass = '') {
  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('width', String(size));
  svg.setAttribute('height', String(size));
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '1.5');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  if (extraClass) svg.setAttribute('class', extraClass);
  svg.innerHTML = P[name] || P.roleGeneric;
  return svg;
}

export function osIcon(os, size = 18) {
  const key = String(os || '').toLowerCase();
  const map = { macos: 'osMac', mac: 'osMac', windows: 'osWindows', linux: 'osLinux', android: 'osAndroid', ios: 'osIos' };
  return icon(map[key] || 'osUnknown', size);
}

